testsCode:
import unittest

from solucao import montar_pedidos
from solucao import conta_da_mesa
from solucao import pratos_do_dia
from solucao import relatorio_do_cardapio
from solucao import guardar_combinacao


class TestFechandoACantina(unittest.TestCase):
    def test_montar_pedidos_agrupa_os_itens_por_mesa(self):
        """montar_pedidos junta os itens da mesma mesa, na ordem e sem espacos"""
        linhas = [" 3;pizza", "3; suco ", "5;salada"]
        self.assertEqual(montar_pedidos(linhas), {"3": ["pizza", "suco"], "5": ["salada"]})

    def test_conta_da_mesa_soma_os_precos_e_arredonda(self):
        """conta_da_mesa soma os precos dos pratos e conta zero o que nao tem preco"""
        pedidos = {"3": ["pizza", "suco"], "5": ["salada"]}
        precos = {"pizza": 42.9, "suco": 9.9}
        self.assertEqual(conta_da_mesa(pedidos, precos, "3"), 52.8)
        self.assertEqual(conta_da_mesa(pedidos, precos, "5"), 0)

    def test_pratos_do_dia_junta_os_pratos_de_todas_as_mesas(self):
        """pratos_do_dia devolve o conjunto dos pratos sem repetir"""
        pedidos = {"3": ["pizza", "suco"], "5": ["salada", "pizza"], "7": ["suco"]}
        self.assertEqual(pratos_do_dia(pedidos), {"pizza", "suco", "salada"})

    def test_relatorio_do_cardapio_conta_fora_dentro_e_se_cabe(self):
        """relatorio_do_cardapio devolve o que saiu, o que entrou e se tudo cabia"""
        pedidos = {"3": ["pizza", "suco"], "5": ["salada"]}
        self.assertEqual(relatorio_do_cardapio(pedidos, {"pizza", "salada"}), ({"suco"}, {"pizza", "salada"}, False))
        self.assertEqual(relatorio_do_cardapio(pedidos, {"pizza", "suco", "salada"}), (set(), {"pizza", "suco", "salada"}, True))

    def test_guardar_combinacao_deteta_o_pedido_repetido(self):
        """guardar_combinacao devolve True quando a combinacao ja foi vista, em qualquer ordem"""
        vistos = {}
        self.assertFalse(guardar_combinacao(vistos, [3, 1, 3]))
        self.assertTrue(guardar_combinacao(vistos, [1, 3]))
        self.assertTrue(guardar_combinacao(vistos, [3, 1]))
        self.assertTrue(guardar_combinacao(vistos, [1, 1, 3]))
        self.assertFalse(guardar_combinacao(vistos, [1, 2]))

