def montar_pedidos(linhas):
    pedidos = {}
    for linha in linhas:
        partes = linha.split(";")
        mesa = partes[0].strip()
        prato = partes[1].strip()
        lista = pedidos.setdefault(mesa, [])
        lista.append(prato)
    return pedidos


def conta_da_mesa(pedidos, precos, mesa):
    total = 0
    for prato in pedidos[mesa]:
        total += precos.get(prato, 0)
    return round(total, 2)


def pratos_do_dia(pedidos):
    todos = set()
    for lista in pedidos.values():
        todos = todos.union(set(lista))
    return todos


def relatorio_do_cardapio(pedidos, cardapio):
    todos = pratos_do_dia(pedidos)
    return todos.difference(cardapio), todos.intersection(cardapio), todos.issubset(cardapio)


def guardar_combinacao(vistos, itens):
    chave = frozenset(itens)
    if chave in vistos:
        return True
    vistos[chave] = True
    return False
